<script>document.addEventListener('DOMContentLoaded',()=>{const modal=document.querySelector('#status-confirm-modal'),message=document.querySelector('#confirm-message'),cancel=document.querySelector('#confirm-cancel'),continueButton=document.querySelector('#confirm-continue');let pending=null;const close=()=>{modal.hidden=true;pending=null};document.querySelectorAll('.status-confirm-form').forEach(form=>form.addEventListener('submit',event=>{if(form.querySelector('[name="status"]').value!=='Transmitted')return;event.preventDefault();pending=form;message.textContent=form.dataset.confirmMessage;modal.hidden=false;cancel.focus()}));cancel.onclick=close;continueButton.onclick=()=>{if(pending){const form=pending;close();form.submit()}};modal.querySelector('.confirm-backdrop').onclick=close;document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)close()})});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('.search');if(!form)return;const sort=document.createElement('select');sort.name='sort';sort.setAttribute('aria-label','Sort transmittals');sort.innerHTML='<option value="updated_desc">Updated: newest first</option><option value="updated_asc">Updated: oldest first</option><option value="date_desc">Transmittal date: newest first</option><option value="date_asc">Transmittal date: oldest first</option><option value="ref_asc">Reference: A–Z</option>';sort.value='{{ request('sort','updated_desc') }}';sort.addEventListener('change',()=>form.submit());form.append(sort);});</script>
